quiz.question:
Prečo je tento UPDATE nebezpečný?

UPDATE tasks
SET done = 1;

tests.code:
const expected = [
  { name: 'David', open_tasks: 3 },
  { name: 'Anna', open_tasks: 2 },
  { name: 'Maria', open_tasks: 0 },
  { name: 'Peter', open_tasks: 0 }
];
const actual = results[results.length - 1];
if (actual.length !== expected.length) return false;
return actual.every((row, index) => row.name === expected[index].name && Number(row.open_tasks) === expected[index].open_tasks);

const actual = results[results.length - 1];
const peter = actual.find(row => row.name === 'Peter');
return !!peter && Number(peter.open_tasks) === 0;

const actual = results[results.length - 1];
const maria = actual.find(row => row.name === 'Maria');
return !!maria && Number(maria.open_tasks) === 0;
